public void refreshBatchClosure(String batchId) {
    if (batchId == null) return;
    CutoverBatchPO batch = batchRepo.lockBatch(batchId); // lock to serialize close
    if (batch == null || !PUBLISHED) return;
    if (batchRepo.countNonTerminalMembers(batchId) == 0) {
        batchRepo.closeBatch(batchId, now);
    }
}
```

